const uuid = () => 'xxxxxxxx-xxxx-4xxx-yxxx-xxxxxxxxxxxx'.replace(/[xy]/g, (character) => {
  const random = Math.floor(Math.random() * 16);
  const value = character === 'x' ? random : ((random & 3) | 8);
  return value.toString(16);
});
const input = $json || {};
const body = input.body && typeof input.body === 'object'
  ? input.body
  : {};
const headers = input.headers || {};
const authHeader = String(
  headers.authorization ||
  headers.Authorization ||
  ''
).trim();
const operation = String(body.operation || '').trim();

const operationMap = {
  'marks.batch.decision': 'rpc_decide_marks_batch',
  'marks.batch.decide': 'rpc_decide_marks_batch',
  'marks.correction.decision': 'rpc_decide_mark_correction',
  'marks.correction.decide': 'rpc_decide_mark_correction',
  'results.publish': 'rpc_publish_results',
};

let rpcName = operationMap[operation] || '';
const webhookUrl = String(input.webhookUrl || '');
if (!rpcName && webhookUrl.includes('rpc_decide_marks_batch')) {
  rpcName = 'rpc_decide_marks_batch';
}
if (!rpcName && webhookUrl.includes('rpc_decide_mark_correction')) {
  rpcName = 'rpc_decide_mark_correction';
}
if (!rpcName && webhookUrl.includes('rpc_publish_results')) {
  rpcName = 'rpc_publish_results';
}

const correlationId =
  String(body.correlation_id || '').trim() ||
  uuid();

const request = {
  ...body,
  correlation_id: correlationId,
  source: {
    ...(body.source && typeof body.source === 'object'
      ? body.source
      : {}),
    channel: 'staff_portal_n8n_webhook',
  },
};

return {
  json: {
    authHeader,
    rpcName,
    request,
    correlationId,
    requestReady:
      authHeader.toLowerCase().startsWith('bearer ') &&
      Boolean(rpcName) &&
      body &&
      typeof body === 'object',
  },
};

const source = $('Normalize Staff Results Request').item.json;
const raw = $json || {};
let body = Object.prototype.hasOwnProperty.call(raw, 'body')
  ? raw.body
  : raw;

if (typeof body === 'string') {
  try {
    body = JSON.parse(body);
  } catch {
    body = {};
  }
}

const statusCode = Number(raw.statusCode ?? raw.status ?? 0);
const userId = String(body?.id || '').trim();
const email = String(body?.email || '').trim().toLowerCase();
const authenticated =
  statusCode >= 200 &&
  statusCode < 300 &&
  Boolean(userId) &&
  email.includes('@');

if (!authenticated) {
  return {
    json: {
      authVerified: false,
      finalResponse: {
        success: false,
        operation: source.request?.operation || 'results.staff.request',
        correlation_id: source.correlationId,
        error: {
          code: 'AUTH_SESSION_INVALID',
          message: 'Your staff session is invalid or expired. Sign in again.',
          retryable: false,
        },
      },
    },
  };
}

const request = {
  ...source.request,
  requester: {
    identity_verified: true,
    verified_auth_user_id: userId,
    verified_email: email,
    verification_source: 'supabase_auth_user_endpoint',
  },
};

return {
  json: {
    authVerified: true,
    rpcName: source.rpcName,
    request,
    correlationId: source.correlationId,
  },
};

const raw = $json || {};

if (raw.finalResponse && typeof raw.finalResponse === 'object') {
  return { json: raw.finalResponse };
}

let body = Object.prototype.hasOwnProperty.call(raw, 'body')
  ? raw.body
  : raw;

if (typeof body === 'string') {
  try {
    body = JSON.parse(body);
  } catch {
    body = null;
  }
}

if (Array.isArray(body) && body.length === 1) {
  body = body[0];
}

if (body && typeof body === 'object' && typeof body.success === 'boolean') {
  return { json: body };
}

const statusCode = Number(raw.statusCode ?? raw.status ?? 0);
return {
  json: {
    success: false,
    operation: 'results.staff.request',
    correlation_id:
      $('Normalize Staff Results Request').item.json.correlationId,
    error: {
      code:
        statusCode >= 500
          ? 'SYSTEM_TEMPORARY_FAILURE'
          : 'RESULT_WORKFLOW_RESPONSE_INVALID',
      message: 'The results operation could not be completed.',
      retryable: statusCode >= 500 || statusCode === 0,
    },
  },
};

const source = $('Normalize Staff Results Request').item.json;
return {
  json: {
    success: false,
    operation: source.request?.operation || 'results.staff.request',
    correlation_id: source.correlationId,
    error: {
      code: 'VALIDATION_REQUEST_INVALID',
      message: 'The staff results request is incomplete or unsupported.',
      retryable: false,
    },
  },
};

const row = $json || {};
const text = (value) =>
  value == null ? '' : String(value).trim();
const uuid = () => 'xxxxxxxx-xxxx-4xxx-yxxx-xxxxxxxxxxxx'.replace(/[xy]/g, (character) => {
  const random = Math.floor(Math.random() * 16);
  const value = character === 'x' ? random : ((random & 3) | 8);
  return value.toString(16);
});
const uuidPattern =
  /^[0-9a-f]{8}-[0-9a-f]{4}-[1-5][0-9a-f]{3}-[89ab][0-9a-f]{3}-[0-9a-f]{12}$/i;
const queue = {
  formResponseId: text(row['Form Response ID']),
  retryCount: Number(row['Retry Count'] || 0),
};
const status = text(row['Processing Status']).toLowerCase();
const operation = text(row['Operation']);
const processable =
  (status === '' || status === 'pending') &&
  operation === 'marks.correction.request';

if (!processable) {
  return {
    json: {
      processable: false,
      queue,
      skipReason:
        status && status !== 'pending'
          ? 'QUEUE_ROW_NOT_PENDING'
          : 'QUEUE_OPERATION_MISMATCH',
    },
  };
}

let raw = row['Raw Response JSON'];
if (typeof raw === 'string') {
  try {
    raw = JSON.parse(raw);
  } catch {
    raw = null;
  }
}

const get = (...titles) => {
  if (!raw || typeof raw !== 'object' || Array.isArray(raw)) {
    return '';
  }
  for (const title of titles) {
    if (Object.prototype.hasOwnProperty.call(raw, title)) {
      const value = raw[title];
      if (Array.isArray(value)) return value.join(', ');
      return text(value);
    }
  }
  return '';
};

const now = new Date().toISOString();
const correlationId = uuid();
const idempotencyKey =
  text(row['Idempotency Key']) ||
  `google-form:${text(row['Source Form ID'])}:${queue.formResponseId}`;

const fail = (code, message) => ({
  json: {
    processable: true,
    requestReady: false,
    'Form Response ID': queue.formResponseId,
    'Processing Status': 'failed',
    'Processed At UTC': now,
    'Correlation ID': correlationId,
    'Error Code': code,
    'Error Message': message,
    'Retry Count': queue.retryCount,
    'Last Attempt At UTC': now,
    'n8n Execution ID': $execution.id,
    success: false,
  },
});

if (!queue.formResponseId) {
  return fail(
    'VALIDATION_FORM_RESPONSE_ID_REQUIRED',
    'The correction queue row has no response identifier.'
  );
}
if (!raw || typeof raw !== 'object' || Array.isArray(raw)) {
  return fail(
    'VALIDATION_RAW_RESPONSE_JSON',
    'The correction form response could not be read.'
  );
}

const institutionCode = get('Institution code').toUpperCase();
const campusCode = get('Campus code').toUpperCase();
const marksBatchId = get('Marks batch ID');
const studentMarkId = get('Student mark ID');
const studentNumber = get('Student number').toUpperCase();
const assessmentCode = get('Assessment code').toUpperCase();
const currentMarksText = get('Current marks');
const proposedMarksText = get('Proposed corrected marks');
const reason = get('Detailed reason for correction');
const evidenceUrl = get('Supporting evidence Drive URL (optional)');
const declaration = get(
  'I confirm that this request is accurate and auditable.'
).toLowerCase();
const requesterEmail = text(row['Respondent Email']).toLowerCase();

if (!institutionCode || !campusCode) {
  return fail(
    'VALIDATION_CORRECTION_SCOPE_REQUIRED',
    'Institution and campus codes are required.'
  );
}
if (!uuidPattern.test(marksBatchId) || !uuidPattern.test(studentMarkId)) {
  return fail(
    'VALIDATION_CORRECTION_UUID_INVALID',
    'Marks batch ID and student mark ID must be valid UUID values.'
  );
}
if (!studentNumber || !assessmentCode) {
  return fail(
    'VALIDATION_CORRECTION_REFERENCE_REQUIRED',
    'Student number and assessment code are required.'
  );
}
const currentMarks = Number(currentMarksText);
const proposedMarks = Number(proposedMarksText);
if (
  currentMarksText === '' ||
  proposedMarksText === '' ||
  !Number.isFinite(currentMarks) ||
  !Number.isFinite(proposedMarks) ||
  currentMarks < 0 ||
  proposedMarks < 0
) {
  return fail(
    'VALIDATION_CORRECTION_MARKS_INVALID',
    'Current and proposed marks must be valid non-negative numbers.'
  );
}
if (reason.length < 10) {
  return fail(
    'VALIDATION_CORRECTION_REASON_REQUIRED',
    'A detailed correction reason is required.'
  );
}
if (evidenceUrl && !/^https:\/\//i.test(evidenceUrl)) {
  return fail(
    'VALIDATION_EVIDENCE_URL_INVALID',
    'The supporting evidence URL must use HTTPS.'
  );
}
if (!declaration.includes('confirm')) {
  return fail(
    'VALIDATION_DECLARATION_REQUIRED',
    'The correction declaration must be confirmed.'
  );
}
if (!requesterEmail.includes('@')) {
  return fail(
    'AUTH_VERIFIED_EMAIL_REQUIRED',
    'The form did not provide a collected respondent email.'
  );
}

const request = {
  operation: 'marks.correction.request',
  correlation_id: correlationId,
  idempotency_key: idempotencyKey,
  requester: {
    email: requesterEmail,
    type: 'google_form_collected_email',
  },
  submitted_at:
    text(row['Submitted At UTC']) || now,
  source: {
    channel: 'google_forms',
    source_form_id: text(row['Source Form ID']),
    source_spreadsheet_id: text(row['Source Spreadsheet ID']),
    source_submission_id: queue.formResponseId,
  },
  payload: {
    institution_code: institutionCode,
    campus_code: campusCode,
    marks_batch_id: marksBatchId,
    student_mark_id: studentMarkId,
    student_number: studentNumber,
    assessment_code: assessmentCode,
    current_marks: currentMarks,
    proposed_marks: proposedMarks,
    reason,
    evidence_drive_url: evidenceUrl || null,
  },
};

return {
  json: {
    processable: true,
    requestReady: true,
    queue,
    request,
    correlationId,
    idempotencyKey,
  },
};

const source = $('Normalize Correction Queue Row').item.json;
const raw = $json || {};
let body = Object.prototype.hasOwnProperty.call(raw, 'body')
  ? raw.body
  : raw;

if (typeof body === 'string') {
  try {
    body = JSON.parse(body);
  } catch {
    body = { message: body };
  }
}
if (Array.isArray(body) && body.length === 1) {
  body = body[0];
}

const statusValue = raw.statusCode ?? raw.status ?? null;
const statusCode =
  statusValue == null
    ? (raw.error ? 0 : 200)
    : Number(statusValue);
const bodyError =
  body && typeof body === 'object'
    ? (
        body.error && typeof body.error === 'object'
          ? body.error
          : body
      )
    : {};
const success =
  statusCode >= 200 &&
  statusCode < 300 &&
  body &&
  typeof body === 'object' &&
  body.success === true;
const retryable = bodyError.retryable === true;
const now = new Date().toISOString();

return {
  json: {
    'Form Response ID': source.queue.formResponseId,
    'Processing Status': success ? 'completed' : 'failed',
    'Processed At UTC': now,
    'Correlation ID':
      body?.correlation_id || source.request.correlation_id,
    'Error Code': success
      ? ''
      : String(
          bodyError.code ||
          bodyError.error_code ||
          (statusCode > 0
            ? `HTTP_${statusCode}`
            : 'NETWORK_FAILURE')
        ).slice(0, 100),
    'Error Message': success
      ? ''
      : String(
          bodyError.message ||
          bodyError.error_message ||
          'The mark correction request could not be completed.'
        ).slice(0, 300),
    'Retry Count':
      source.queue.retryCount +
      (!success && retryable ? 1 : 0),
    'Last Attempt At UTC': now,
    'n8n Execution ID': $execution.id,
    correctionRequestId:
      body?.data?.correction_request_id || '',
    rpcResult: body,
    success,
  },
};
